(7079832, 1076782, 114285, '<td valign="top">Hmmm not sure if I''ve seen bear do a street shot at a train station, I could be wrong though, I''ve been known to be wrong!</td>', 'Hmmm not sure if I''ve seen bear do a street shot at a train station, I could be wrong though, I''ve been known to be wrong!', '2013-08-01 05:10:53.000000', NULL, 1),
(7079836, 1076949, 22459, '<td valign="top">Delightfull</td>', 'Delightfull', '2013-08-01 06:05:59.000000', NULL, 1),
(7079846, 1076717, 103142, '<td valign="top">Powerful. Incredibly powerful. I can''t believe you had second thoughts about entering it. I''m so glad you left it in. 10 from me.</td>', 'Powerful. Incredibly powerful. I can''t believe you had second thoughts about entering it. I''m so glad you left it in. 10 from me.', '2013-08-01 07:47:10.000000', NULL, 1),
