(7080280, 1076202, 10785, '<td valign="top">A nice tribute to <a href="//www.dpchallenge.com/image.php?IMAGE_ID=1070523" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/1000-1999/1755/120/Copyrighted_Image_Reuse_Prohibited_1070523.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/1000-1999/1755/120/Copyrighted_Image_Reuse_Prohibited_1070523.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/1000-1999/1755/120/Copyrighted_Image_Reuse_Prohibited_1070523.jpg"/></a>!</td>', 'A nice tribute to !', '2013-08-01 21:24:38.000000', NULL, 1),
(7080282, 1076880, 30861, '<td valign="top">It''s a little-known fact that bears like moose, feel a kinship with them. It''s not uncommon to see groups of bears congregating in the early morning at the edge of shallow waters to watch the moose feeding and exchange friendly jibes back and forth with them. Clearly, this moose is in the act of formulating his riposte to the watching bears. Well done!<br/> <br/>I miss the mountains. But I''d miss the ocean more.<br/> <br/>******<br/> <br/>It''s a Bear kind of place, and my spirit rests easy in it, even at this remove. For that sense of peace, that feeling of "all''s well", I give you a Bronze Bear Paw.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=762725" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/30000-34999/30861/120/Copyrighted_Image_Reuse_Prohibited_762725.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/30000-34999/30861/120/Copyrighted_Image_Reuse_Prohibited_762725.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/30000-34999/30861/120/Copyrighted_Image_Reuse_Prohibited_762725.jpg"/></a></td>', 'It''s a little-known fact that bears like moose, feel a kinship with them. It''s not uncommon to see groups of bears congregating in the early morning at the edge of shallow waters to watch the moose feeding and exchange friendly jibes back and forth with them. Clearly, this moose is in the act of formulating his riposte to the watching bears. Well done! I miss the mountains. But I''d miss the ocean more. ****** It''s a Bear kind of place, and my spirit rests easy in it, even at this remove. For that sense of peace, that feeling of "all''s well", I give you a Bronze Bear Paw. ', '2013-08-01 21:27:08.000000', NULL, 1),
(7080284, 1076712, 30861, '<td valign="top">In so many ways this feels like a penetrating echo of places I have been and how I''ve seen them, BUT... and it''s a big "but"... the skewed horizon drives me mad! Love the processing and the scene, the tones, the conversion.<br/> <br/>*******<br/> <br/>Still, it''s a wonderful, Beary place and light, and I give you a Bronze Bear Paw.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=762725" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/30000-34999/30861/120/Copyrighted_Image_Reuse_Prohibited_762725.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/30000-34999/30861/120/Copyrighted_Image_Reuse_Prohibited_762725.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/30000-34999/30861/120/Copyrighted_Image_Reuse_Prohibited_762725.jpg"/></a></td>', 'In so many ways this feels like a penetrating echo of places I have been and how I''ve seen them, BUT... and it''s a big "but"... the skewed horizon drives me mad! Love the processing and the scene, the tones, the conversion. ******* Still, it''s a wonderful, Beary place and light, and I give you a Bronze Bear Paw. ', '2013-08-01 21:28:03.000000', NULL, 1),
(7080288, 1076919, 30861, '<td valign="top">I want that knife!<br/> <br/>*******<br/> <br/>In fact, that knife and those paper-thin slices resonate so much with me my spirit (as opposed to my head) insists on giving you a Bronze Bear Paw :-)<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=762725" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/30000-34999/30861/120/Copyrighted_Image_Reuse_Prohibited_762725.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/30000-34999/30861/120/Copyrighted_Image_Reuse_Prohibited_762725.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/30000-34999/30861/120/Copyrighted_Image_Reuse_Prohibited_762725.jpg"/></a></td>', 'I want that knife! ******* In fact, that knife and those paper-thin slices resonate so much with me my spirit (as opposed to my head) insists on giving you a Bronze Bear Paw :-) ', '2013-08-01 21:29:44.000000', NULL, 1),
